import Foundation

// MARK: - 学校配置

/// 学校 id。登录页选择器直接读 schools 表。
enum SchoolID: String, CaseIterable {
    case gut = "gut"
    case gxvnu = "gxvnu"
}

/// 每所学校的教务配置。默认桂工。
struct SchoolConfig: Equatable {
    let id: SchoolID
    /// App 内显示名。
    let displayName: String
    /// 教务域名，如 jw.glutnn.cn / jw.gxvnu.edu.cn。
    let host: String
    /// 是否用 HTTPS（桂工纯 HTTP，职师院 HTTPS）。
    let useHttps: Bool
    /// 接口路径前缀：桂工 ""，正方 V9.0 "/jwglxt"。
    let pathPrefix: String
    /// 正方 V9.0 功能模块代码（gnmkdm）。桂工不用。
    let gnmkdm: [String: String]
    /// 登录默认是否需要验证码（桂工每次都要，职师院默认不要）。
    let captchaRequired: Bool
    /// 本学期第一周的周一（用于算当前周）。
    let termStartDate: Date
    /// 每节课开始时间 [时, 分]，共 11 条。
    let startTimeList: [(Int, Int)]
    /// 每节课结束时间 [时, 分]，共 11 条。
    let endTimeList: [(Int, Int)]

    var sectionCount: Int { startTimeList.count }

    /// 生效的开始时间：有自定义（时间管理）就用自定义，否则用学校默认作息。
    /// 自定义条数不对或格式不对就退回默认，不会崩。
    var effectiveStartTimeList: [(Int, Int)] {
        if let custom = CustomSectionTimes.load(for: id),
           custom.start.count == startTimeList.count,
           custom.start.allSatisfy({ $0.count == 2 }) {
            return custom.start.map { ($0[0], $0[1]) }
        }
        return startTimeList
    }

    /// 生效的结束时间：同上。
    var effectiveEndTimeList: [(Int, Int)] {
        if let custom = CustomSectionTimes.load(for: id),
           custom.end.count == endTimeList.count,
           custom.end.allSatisfy({ $0.count == 2 }) {
            return custom.end.map { ($0[0], $0[1]) }
        }
        return endTimeList
    }

    /// 生效的开学日期：学期设置里改过就用改过的，否则用学校默认开学日。
    var effectiveTermStartDate: Date {
        AppSettings.termStartDateOverride(for: id) ?? termStartDate
    }

    /// 生效的学期总周数（学期设置，默认 20）。
    var effectiveTotalWeeks: Int { AppSettings.totalWeeks(for: id) }

    static func == (lhs: SchoolConfig, rhs: SchoolConfig) -> Bool {
        lhs.id == rhs.id
    }

    /// 按本校 scheme/host/prefix 拼接口地址。
    func url(_ path: String, query: [String: String]? = nil) -> URL? {
        let fullPath = pathPrefix + path
        var components = URLComponents()
        components.scheme = useHttps ? "https" : "http"
        components.host = host
        components.path = fullPath
        if let query, !query.isEmpty {
            components.queryItems = query.map { URLQueryItem(name: $0.key, value: $0.value) }
        }
        return components.url
    }
}

private func date(_ y: Int, _ m: Int, _ d: Int) -> Date {
    var c = DateComponents()
    c.year = y; c.month = m; c.day = d
    return Calendar(identifier: .gregorian).date(from: c) ?? Date()
}

