/// 平均绩点：只算 gpaCourseCategories 类别、且不在排除名单里的课。
/// 慕课（课程名含“慕课”且无老师）不计入。
func gradePointAverage(_ scores: [CourseScore]) -> Double {
    var totalGP = 0.0
    var totalCredit = 0.0
    for s in scores {
        if s.courseName.contains("慕课") && s.teacher.isEmpty { continue }
        if gpaCourseCategories.contains(s.courseCategory) && !excludedCourseCodes.contains(s.courseCode) {
            totalGP += s.gradePoint * s.credit
            totalCredit += s.credit
        }
    }
    guard totalCredit > 0 else { return 0 }
    return (totalGP / totalCredit * 100).rounded() / 100
}

/// 平均分：慕课（课程名含“慕课”且无老师）不计入。
func averageScore(_ scores: [CourseScore]) -> Double {
    let counted = scores.filter { !($0.courseName.contains("慕课") && $0.teacher.isEmpty) }
    guard !counted.isEmpty else { return 0 }
    let total = counted.reduce(0.0) { $0 + $1.score }
    return (total / Double(counted.count) * 100).rounded() / 100
}

/// 成绩每行显示的文字（build 63 通用设置：0=原始成绩，1=绩点，2=数字分）。
func scoreRowText(_ s: CourseScore) -> String {
    switch AppSettings.scoreDisplayMode {
    case 1:
        return String(format: "%.2f", s.gradePoint)
    case 2:
        return String(format: "%.1f", s.score)
    default:
        return s.rawScore
    }
}


// MARK: - 首页壁纸（Flutter 版校园黄昏照片）
//
// 从 Flutter 版 glass_wallpaper_b64 提取的同一张图，压缩到 800px / q48 后
// 内嵌 base64（约 103KB），避免新增资源文件改 pbxproj。
// 运行时解码成图片，供 WindowGroup 层背景用。
let wallpaperBase64 = """

"""

/// 壁纸图片数据（base64 解码）。解码失败返回 nil，调用方用纯色兜底。
func wallpaperImageData() -> Data? {
    Data(base64Encoded: wallpaperBase64, options: .ignoreUnknownCharacters)
}

/// 自定义壁纸文件（Documents/custom-wallpaper.jpg；UserDefaults 放不下大图）。
/// build 69：Russell 要从相册选壁纸（首页设置 → 壁纸 → 自定义照片）。
var customWallpaperURL: URL {
    FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        .appendingPathComponent("custom-wallpaper.jpg")
}

/// 存自定义壁纸（相册选图后调）。存失败静默忽略，调用方读不到就退回默认壁纸。
func saveCustomWallpaper(_ data: Data) {
    try? data.write(to: customWallpaperURL)
}

/// 读自定义壁纸。没存过返回 nil。
func customWallpaperData() -> Data? {
    try? Data(contentsOf: customWallpaperURL)
}

/// 是否已存自定义壁纸。
func hasCustomWallpaper() -> Bool {
    FileManager.default.fileExists(atPath: customWallpaperURL.path)
}
